import json, sys, time, itertools
import numpy as np
from sentence_transformers import SentenceTransformer

R = "/workspace/.claude/worktrees/agent-a12e15f03a8f47b80/case"
cat = [json.loads(l) for l in open(f"/assets/catalog.jsonl")]
tr = [json.loads(l) for l in open(f"{R}/dataset/train.jsonl")]
meta = {m["id"]: m for m in map(json.loads, open(f"{R}/dataset/train.meta.jsonl"))}
curve = {json.loads(l)["id"] for l in open(f"{R}/dataset/train_curve.jsonl")}
ids = [c["id"] for c in cat]
rel = []
for e in tr:
    r = json.loads(e["reference"]); rel.append({r["primary"], *r["acceptable"]})

QP = {"bge": "Represent this sentence for searching relevant passages: ", "e5": "query: "}
DP = {"e5": "passage: "}

def docs(field):
    if field == "nd": return [f'{c["name"]}. {c["description"]}' for c in cat]
    if field == "colon": return [f'{c["name"]}: {c["description"]}' for c in cat]
    if field == "d": return [c["description"] for c in cat]
    if field == "idnd": return [f'{c["id"]} {c["name"]}. {c["description"]}' for c in cat]

def score(S):
    top = np.argsort(-S, axis=1)[:, :3]
    out = []
    for i, e in enumerate(tr):
        t = [ids[j] for j in top[i]]
        a1 = float(t[0] in rel[i]); n3 = len(set(t) & rel[i]) / min(3, len(rel[i]))
        out.append((0.7 * a1 + 0.3 * n3, a1, n3))
    return np.array(out)

def report(name, S):
    sc = score(S)
    inc = np.array([e["id"] in curve for e in tr])
    sty = np.array([meta[e["id"]]["style"] for e in tr])
    print(f"{name:40s} all {sc[:,0].mean():.3f} (acc1 {sc[:,1].mean():.3f}) curve {sc[inc,0].mean():.3f} rest {sc[~inc,0].mean():.3f} | "
          + " ".join(f"{s[:4]} {sc[sty==s,1].mean():.2f}" for s in ["cmd", "verbose", "question", "casual", "typo", "indirect"]), flush=True)

if __name__ == "__main__":
    models = sys.argv[1].split(",")
    for m in models:
        st = SentenceTransformer(f"/assets/models/{m}", device="cpu")
        fam = "bge" if m.startswith("bge") else "e5" if m.startswith("e5") else "none"
        qvars = [("", "")]
        if fam == "bge": qvars.append(("inst", QP["bge"]))
        if fam == "e5": qvars = [("q:", QP["e5"])]
        for field in ["nd", "d", "colon"]:
            D = docs(field)
            dp = DP.get(fam, "")
            E = st.encode([dp + d for d in D], normalize_embeddings=True, batch_size=64)
            for qn, qp in qvars:
                Q = st.encode([qp + e["input"] for e in tr], normalize_embeddings=True, batch_size=64)
                report(f"{m} {field} q={qn}", Q @ E.T)

